'use client';

import { FormEvent, useEffect, useState } from 'react';
import Image from 'next/image';
import QRCode from 'qrcode';

const sizeOptions = [100, 200, 300, 400, 500, 600, 700];

export default function HomePage() {
  const [url, setUrl] = useState('');
  const [size, setSize] = useState('300');
  const [qrDataUrl, setQrDataUrl] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    setIsLoading(false);
  }, []);

  const generateQRCode = async (value: string, dimension: string) => {
    const dataUrl = await QRCode.toDataURL(value, {
      width: Number(dimension),
      margin: 2,
      color: {
        dark: '#000000',
        light: '#FFFFFF',
      },
    });

    setQrDataUrl(dataUrl);
  };

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    if (!url.trim()) {
      window.alert('Please enter a URL');
      return;
    }

    setIsLoading(true);
    setQrDataUrl('');

    setTimeout(async () => {
      try {
        await generateQRCode(url, size);
      } finally {
        setIsLoading(false);
      }
    }, 1000);
  };

  return (
    <>
      <header className="p-4 mb-10 bg-red-500">
        <div className="max-w-5xl m-auto">
          <div className="text-xl font-bold text-white">QR Code Generator</div>
        </div>
      </header>

      <main>
        <div className="flex flex-col-reverse items-center justify-center m-auto md:max-w-4xl p-10 md:flex-row md:items-center">
          <div className="w-full md:w-2/3 md:mr-24">
            <h1 className="text-3xl font-bold mb-5 md:text-4xl">QR Code Generator</h1>
            <p className="mb-4 text-slate-700">
              QR Codes allow smartphone users to access your website simply and quickly.
            </p>
            <p className="text-slate-700">
              Enter your URL below to generate a QR Code and download the image.
            </p>

            <form id="generate-form" className="mt-4" onSubmit={handleSubmit}>
              <input
                id="url"
                type="url"
                placeholder="Enter a URL"
                className="w-full border-2 border-gray-200 rounded p-3 text-gray-700 mr-2 focus:outline-none mb-5"
                required
                value={url}
                onChange={(e) => setUrl(e.target.value)}
              />

              <select
                className="w-full border-2 border-gray-200 rounded p-3 text-gray-700 mr-2 focus:outline-none"
                name="size"
                id="size"
                value={size}
                onChange={(e) => setSize(e.target.value)}
              >
                {sizeOptions.map((option) => (
                  <option key={option} value={String(option)}>
                    {option}x{option}
                  </option>
                ))}
              </select>

              <button
                className="bg-gray-600 rounded w-full text-white py-3 px-4 mt-5 hover:bg-black"
                type="submit"
              >
                Generate QR Code
              </button>
            </form>
          </div>

          <div className="w-full md:w-1/3 self-center mb-10 md:mb-0">
            <Image
              className="w-1/2 m-auto md:w-full"
              src="/img/qr-code.svg"
              alt="QR code illustration"
              width={300}
              height={300}
            />
          </div>
        </div>

        <div className="max-w-5xl m-auto flex flex-col text-center items-center justify-center mt-20">
          {isLoading && (
            <div id="spinner" role="status" className="mb-5">
              <svg
                className="inline mr-2 w-24 h-24 text-gray-200 animate-spin fill-pink-600"
                viewBox="0 0 100 101"
                fill="none"
                xmlns="http://www.w3.org/2000/svg"
              >
                <path
                  d="M100 50.5908C100 78.2051 77.6142 100.591 50 100.591C22.3858 100.591 0 78.2051 0 50.5908C0 22.9766 22.3858 0.59082 50 0.59082C77.6142 0.59082 100 22.9766 100 50.5908ZM9.08144 50.5908C9.08144 73.1895 27.4013 91.5094 50 91.5094C72.5987 91.5094 90.9186 73.1895 90.9186 50.5908C90.9186 27.9921 72.5987 9.67226 50 9.67226C27.4013 9.67226 9.08144 27.9921 9.08144 50.5908Z"
                  fill="currentColor"
                />
                <path
                  d="M93.9676 39.0409C96.393 38.4038 97.8624 35.9116 97.0079 33.5539C95.2932 28.8227 92.871 24.3692 89.8167 20.348C85.8452 15.1192 80.8826 10.7238 75.2124 7.41289C69.5422 4.10194 63.2754 1.94025 56.7698 1.05124C51.7666 0.367541 46.6976 0.446843 41.7345 1.27873C39.2613 1.69328 37.813 4.19778 38.4501 6.62326C39.0873 9.04874 41.5694 10.4717 44.0505 10.1071C47.8511 9.54855 51.7191 9.52689 55.5402 10.0491C60.8642 10.7766 65.9928 12.5457 70.6331 15.2552C75.2735 17.9648 79.3347 21.5619 82.5849 25.841C84.9175 28.9121 86.7997 32.2913 88.1811 35.8758C89.083 38.2158 91.5421 39.6781 93.9676 39.0409Z"
                  fill="currentFill"
                />
              </svg>
              <span className="sr-only">Loading...</span>
            </div>
          )}

          {qrDataUrl && (
            <>
              <div className="m-auto">
                <Image src={qrDataUrl} alt="Generated QR code" width={Number(size)} height={Number(size)} unoptimized />
              </div>
              <a
                href={qrDataUrl}
                download="qrcode"
                className="bg-red-500 hover:bg-red-700 text-white font-bold py-2 px-5 rounded w-1/3 m-auto my-5"
              >
                Save Image
              </a>
            </>
          )}
        </div>
      </main>
    </>
  );
}
